import pathlib,json,hashlib,datetime
P=pathlib.Path(__file__).resolve().parent;SRC=P.parents[1]/'judge-score-fingerprinting-poc'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
# Preserve complete frozen corpus/baseline and both Qwen sibling trees, including existing reviews. Environments/models excluded from full-file hashing; saved data/code/results included.
hashes={}
for folder in ['2026-10-25','2026-10-25-local-qwen','2026-10-25-local-qwen-sensitivity']:
 for p in (SRC/folder).rglob('*'):
  rel=p.relative_to(SRC)
  if any(x in ['.venv','models','__pycache__'] for x in rel.parts) or p.is_symlink() or not p.is_file():continue
  hashes[str(rel)]=sha(p)
(P/'original-hashes.json').write_text(json.dumps(hashes,indent=2))
